PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>
   SELECT DISTINCT $this ?member WHERE {
       $this ucm:consentSubject/ucm:participatingEntity ?hh ;
             ucm:recordsConsentFrom ?ci .
       ?hh a/rdfs:subClassOf* ucm:Household .
       { ?hh ucm:hasMember ?member } UNION { ?member ucm:memberOf ?hh }
       UNION { ?member ucm:hasMembership/ucm:membershipIn ?hh }
?member ucm:birthDate ?bd .
?ci ucm:occursDuring ?when .
?when (time:hasBeginning/(time:inXSDDateTimeStamp|time:inXSDDateTime))|time:inXSDDateTimeStamp|time:inXSDDateTime ?at .
BIND (STR(?bd) AS ?b)
BIND (IF(STRLEN(?b) = 4, CONCAT(?b, "-12-31"), IF(STRLEN(?b) = 7, CONCAT(?b, "-31"), SUBSTR(?b, 1, 10))) AS ?latest)
BIND (SUBSTR(STR(?at), 1, 10) AS ?on)
BIND (xsd:integer(SUBSTR(?on, 1, 4)) - xsd:integer(SUBSTR(?latest, 1, 4))
      - IF(SUBSTR(?on, 6, 5) < SUBSTR(?latest, 6, 5), 1, 0) AS ?age)
FILTER (?age < 18)
       FILTER NOT EXISTS {
           $this ucm:recordsConsentFrom ?pci .
           ?pp ucm:consentOnBehalfOf ?member ;
               ucm:assumesRole/a/rdfs:subClassOf* ucm:ConsentProxyRole .
           { ?pp ucm:occursWithin ?pci } UNION { ?pci ucm:hasParticipant ?pp }
       }
       FILTER NOT EXISTS {
           $this ucm:recordsConsentFrom ?sci ;
                 ucm:governedByPolicy ?rule .
           ?sp ucm:participatingEntity ?member ;
               ucm:assumesRole/a/rdfs:subClassOf* ucm:ConsentGrantorRole .
           { ?sp ucm:occursWithin ?sci } UNION { ?sci ucm:hasParticipant ?sp }
           ?rule a/rdfs:subClassOf* ucm:SelfConsentRule .
           OPTIONAL { ?rule ucm:minimumSelfConsentAge ?min }
           FILTER (!BOUND(?min) || ?age >= ?min)
       }
   }

