    FILTER (xsd:dateTime(STR(?t)) < xsd:dateTime(STR(?f)))
}

PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT $this WHERE {
    # UNION, not VALUES: SHACL forbids VALUES in SPARQL constraints.
    { $this ucm:hasClient   ?person . BIND (ucm:ClientRole   AS ?roleClass) }
    UNION
    { $this ucm:hasPatient  ?person . BIND (ucm:PatientRole  AS ?roleClass) }
    UNION
    { $this ucm:hasResident ?person . BIND (ucm:ResidentRole AS ?roleClass) }
    FILTER NOT EXISTS {
        ?p ucm:participatingEntity ?person ;
           ucm:assumesRole/a/rdfs:subClassOf* ?roleClass .
        { ?p ucm:occursWithin $this } UNION { $this ucm:hasParticipant ?p }
    }
}

PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT $this ?value WHERE {
    $this ucm:hasProofingType ?value .
    FILTER NOT EXISTS { ?value skos:inScheme ?s . FILTER (?s IN (ucm:ProofingType)) }
    FILTER NOT EXISTS {
        ?value (skos:exactMatch|skos:closeMatch|skos:broadMatch|skos:narrowMatch)/skos:inScheme ?m .
        FILTER (?m IN (ucm:ProofingType))
    }
}

PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT $this ?value WHERE {
    ?parent ucm:hasProvision $this ;
            ucm:hasConsentDecision ?pd .
    $this ucm:hasConsentDecision ?value .
    ?pd    (skos:exactMatch|^skos:exactMatch)* ?pn .
    ?value (skos:exactMatch|^skos:exactMatch)* ?vn .
    FILTER (?pn IN (ucm:Permit, ucm:Deny) && ?pn = ?vn)
}

PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT $this ?grantor WHERE {
    $this ucm:recordsConsentFrom ?ci .
    ?gp ucm:assumesRole/a/rdfs:subClassOf* ucm:ConsentGrantorRole .
    { ?gp ucm:occursWithin ?ci } UNION { ?ci ucm:hasParticipant ?gp }
    ?gp ucm:participatingEntity ?grantor .
    $this ucm:consentSubject/ucm:participatingEntity ?subject .
    FILTER (?grantor != ?subject)
    FILTER NOT EXISTS { ?gp ucm:assumesRole/a/rdfs:subClassOf* ucm:ConsentProxyRole }
    # A member of a group subject (such as a household) may grant for themselves.
    FILTER NOT EXISTS { ?subject ucm:hasMember ?grantor }
    FILTER NOT EXISTS { ?grantor ucm:memberOf ?subject }
    FILTER NOT EXISTS { ?grantor ucm:hasMembership/ucm:membershipIn ?subject }
}

