PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dpv:  <https://w3id.org/dpv#>
SELECT $this WHERE {
    {
        $this dpv:hasConsentStatus/(skos:exactMatch|^skos:exactMatch)* ?ended .
        FILTER (?ended IN (dpv:ConsentWithdrawn, dpv:ConsentRevoked))
        FILTER NOT EXISTS { $this ucm:revokedBy ?r }
    } UNION {
        $this ucm:revokedBy ?r ;
              dpv:hasConsentStatus/(skos:exactMatch|^skos:exactMatch)* ucm:ConsentActive .
    }
}

PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT $this ?value WHERE {
    $this ucm:selfConsentCondition ?value .
    FILTER NOT EXISTS { ?value skos:inScheme ?s . FILTER (?s IN (ucm:SelfConsentCondition)) }
    FILTER NOT EXISTS {
        ?value (skos:exactMatch|skos:closeMatch|skos:broadMatch|skos:narrowMatch)/skos:inScheme ?m .
        FILTER (?m IN (ucm:SelfConsentCondition))
    }
}

PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT $this ?value WHERE {
    $this ucm:selfConsentScope ?value .
    FILTER NOT EXISTS { ?value skos:inScheme ?s . FILTER (?s IN (ucm:PurposeOfUse, ucm:ConsentCategory, ucm:InformationCategory, ucm:SensitivityCategory)) }
    FILTER NOT EXISTS {
        ?value (skos:exactMatch|skos:closeMatch|skos:broadMatch|skos:narrowMatch)/skos:inScheme ?m .
        FILTER (?m IN (ucm:PurposeOfUse, ucm:ConsentCategory, ucm:InformationCategory, ucm:SensitivityCategory))
    }
}

PREFIX ucm:  <https://www.w3.org/ns/ucm#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT $this ?value WHERE {
    $this ucm:coversSensitivity|ucm:hasSensitivityLabel ?value .
    FILTER NOT EXISTS { ?value skos:inScheme ?s . FILTER (?s IN (ucm:SensitivityCategory)) }
    FILTER NOT EXISTS {
        ?value (skos:exactMatch|skos:closeMatch|skos:broadMatch|skos:narrowMatch)/skos:inScheme ?m .
        FILTER (?m IN (ucm:SensitivityCategory))
    }
}

PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>
SELECT $this WHERE {
    $this time:hasBeginning/(time:inXSDDateTimeStamp|time:inXSDDateTime) ?b ;
          time:hasEnd/(time:inXSDDateTimeStamp|time:inXSDDateTime) ?e .
    FILTER (xsd:dateTime(STR(?e)) < xsd:dateTime(STR(?b)))
}
